#include "taffy/TaffyItem.h"

#include <QSGFlatColorMaterial>
#include <QSGGeometryNode>

// Generated by cxx-qt from rust/src/layout_engine.rs
#include <taffy_rust/src/layout_engine.cxxqt.h>

TaffyItem::TaffyItem(QQuickItem* parent)
    : QQuickItem(parent)
    , m_engine(new LayoutEngine(this))
{
    setFlag(ItemHasContents, true);
    m_engine->setProperty("spacing", m_spacing);
    m_engine->setProperty("mode", m_mode);
}

TaffyItem::~TaffyItem() = default;

qint32 TaffyItem::mode() const
{
    return m_mode;
}

void TaffyItem::setMode(qint32 mode)
{
    if (m_mode == mode) {
        return;
    }
    m_mode = mode;
    if (m_engine) {
        m_engine->setProperty("mode", m_mode);
    }
    emit modeChanged();
    update();
}

qreal TaffyItem::spacing() const
{
    return m_spacing;
}

void TaffyItem::setSpacing(qreal spacing)
{
    if (qFuzzyCompare(m_spacing, spacing)) {
        return;
    }
    m_spacing = spacing;
    if (m_engine) {
        m_engine->setProperty("spacing", static_cast<float>(m_spacing));
    }
    emit spacingChanged();
    update();
}

QColor TaffyItem::color() const
{
    return m_color;
}

void TaffyItem::setColor(const QColor& color)
{
    if (m_color == color) {
        return;
    }
    m_color = color;
    emit colorChanged();
    update();
}

QSGNode* TaffyItem::updatePaintNode(QSGNode* oldNode, UpdatePaintNodeData*)
{
    auto* node = static_cast<QSGGeometryNode*>(oldNode);
    if (!node) {
        node = new QSGGeometryNode;
        auto* geometry = new QSGGeometry(QSGGeometry::defaultAttributes_Point2D(), 0);
        geometry->setDrawingMode(QSGGeometry::DrawTriangleStrip);
        node->setGeometry(geometry);
        node->setFlag(QSGNode::OwnsGeometry);

        auto* material = new QSGFlatColorMaterial;
        material->setColor(m_color);
        node->setMaterial(material);
        node->setFlag(QSGNode::OwnsMaterial);
    } else {
        static_cast<QSGFlatColorMaterial*>(node->material())->setColor(m_color);
    }

    // Minimal placeholder: one quad. Real layout comes from the Rust engine later.
    const qreal w = width();
    const qreal h = height();
    QSGGeometry* geometry = node->geometry();
    geometry->allocate(4);
    auto* vertices = geometry->vertexDataAsPoint2D();
    vertices[0].set(0, 0);
    vertices[1].set(float(w), 0);
    vertices[2].set(0, float(h));
    vertices[3].set(float(w), float(h));

    node->markDirty(QSGNode::DirtyGeometry | QSGNode::DirtyMaterial);
    return node;
}
